    holdReasonNote: null,
    plannedDate,
    pickupDate: null,
    completedAt: null,
    createdAt: 1706745600000,
    customerName: 'Test Customer',
    bicycleBrand: 'Trek',
    bicycleModel: 'Domane',
    bicycleColor: 'blue',
  }
}

