describe('getRepairsForWeek', () => {
  afterEach(() => {
    vi.clearAllMocks()
  })

  it('calls the repairs endpoint with from, to, and statusIn params', async () => {
    const { getRepairsForWeek } = await importApi()

    const mockRepairs: RepairDetailWithCustomer[] = [
      createMockRepair('r1', 'in_progress', 1706832000000),
    ]

    mockFetch.mockResolvedValueOnce({
      ok: true,
      json: async () => ({ repairs: mockRepairs, total: 1, page: 1, pageSize: 100, totalPages: 1 }),
    })

    const result = await getRepairsForWeek(1706745600000, 1707350400000)

    // Verify the call was made with correct params (URLSearchParams encodes commas as %2C)
    const [calledUrl] = mockFetch.mock.calls[0]
    expect(calledUrl).toContain('from=1706745600000')
    expect(calledUrl).toContain('to=1707350400000')
    // statusIn commas are URL-encoded as %2C
    expect(calledUrl).toContain('statusIn=in_progress%2Con_hold%2Cverified%2Cready')
    expect(calledUrl).toContain('page=1')
    expect(calledUrl).toContain('pageSize=100')
    expect(result.repairs).toHaveLength(1)
    expect(result.repairs[0].id).toBe('r1')
  })

  it('throws when the API response is not ok', async () => {
    const { getRepairsForWeek } = await importApi()

    mockFetch.mockResolvedValueOnce({
      ok: false,
      status: 500,
    })

    await expect(getRepairsForWeek(1706745600000, 1707350400000)).rejects.toThrow('Failed to fetch repairs for week')
  })
})

